// This code checks for hypocrisy in a given statement
function isHypocritical(statement) {
    // Define keywords that might indicate hypocrisy
    const keywords = [say, do, believe, act, claim, preach];

    // Check if the statement contains contradictory keywords
    for (let i = 0; i < keywords.length; i++) {
        if (statement.includes(keywords[i])) {
            for (let j = i + 1; j < keywords.length; j++) {
                if (statement.includes(keywords[j])) {
                    return true; // Hypocrisy detected
                }
            }
        }
    }
    return false; // No hypocrisy detected
}

// Example usage
const comment = Hypocrisy is when people say one thing and do another.;
console.log(isHypocritical(comment)); // Output: true
```

