    return {
        groupName: group.name,
        participants: group.members,
        topics: ['Understanding', 'Empathy', 'Shared Experiences'],
        facilitator: assignFacilitator(),
        outcome: 'Promote mutual respect and reduce racial tension'
    };
}

function assignFacilitator() {
