// This code snippet is a placeholder for a self-defense mechanism in a game or simulation.
// It represents a character's ability to defend itself when under attack.

class Character {
    constructor(name, health) {
        this.name = name;
        this.health = health;
        this.isDefending = false;
    }

    defend() {
        this.isDefending = true;
        console.log(`${this.name} is defending!`);
    }

    takeDamage(amount) {
        if (this.isDefending) {
            console.log(`${this.name} blocked the attack!`);
            this.isDefending = false; // Reset defending state after blocking
        } else {
            this.health -= amount;
            console.log(`${this.name} took ${amount} damage! Health is now ${this.health}.`);
        }
    }
}

// Example usage:
const hero = new Character('Hero', 100);
hero.defend();
hero.takeDamage(20);
```

