// The code below is a qualitative representation of the concept of exploitation in a hypothetical scenario.

class Worker {
    String name;
    double hoursWorked;
    double hourlyRate;

    Worker(String name, double hoursWorked, double hourlyRate) {
        this.name = name;
        this.hoursWorked = hoursWorked;
        this.hourlyRate = hourlyRate;
    }

    double calculateWage() {
        return hoursWorked * hourlyRate;
    }
}

class Employer {
    String name;
    double profitMargin;

    Employer(String name, double profitMargin) {
        this.name = name;
        this.profitMargin = profitMargin;
    }

    double calculateProfit(double revenue) {
        return revenue * profitMargin;
    }

    void exploitWorker(Worker worker) {
        double wage = worker.calculateWage();
        double revenue = wage * 2; // Hypothetical scenario where revenue is double the wage
        double profit = calculateProfit(revenue);
        System.out.println(Employer  + name +  exploits worker  + worker.name +  by generating profit:  + profit);
    }
}

public class ExploitationScenario {
    public static void main(String[] args) {
        Worker worker = new Worker(John Doe, 40, 15);
        Employer employer = new Employer(ABC Corp, 0.3);

        employer.exploitWorker(worker);
    }
}
```

