Mistral R5:
```python
# Qualitative Code: Thematic Codes

thematic_codes = {
    Denial or Minimization of Racism: {
        definition: Refusal to acknowledge or downplay the racist nature of content.,
        example: Reluctance to label offensive generalizations as racist despite their stereotypical nature.
    },
    Claims of Authority Based on Geography and Ethnicity: {
        definition: Asserting expertise on race issues due to geographical diversity or ethnic background.,
        example: Using being from a diverse area like Ohio to claim credibility on race issues, implying inferior understanding from less diverse regions.
    },
    Intersectional Identity and Privilege: {
        definition: Interplay of race, gender, geography, and other identities shaping perspectives and authority in racial discourse.,
        example: The speaker's self-identity as from Oregon (perceived as white) and the interplay with gender in the context of discussing race and crime.
    },
    Power Dynamics in Racial Discourse: {
        definition: Struggle for control and validity in discussions about race, dominated by privileged or authoritative voices.,
        example: A white male lecturing others on race issues, dismissing concerns about racism and reflecting broader power imbalances.
    },
    Resistance to Critique and Dismissal: {
        definition: Pushback against being told to ignore or minimize concerns about racism.,
        example: Defiance against being lectured or lectured about racial validity by privileged individuals, emphasizing the speaker's lived experiences and interpretations.
    },
    Condemnation of Offensive Content: {
        definition: Criticism of potentially racist or offensive content.,
        example: Terms like 'not a good look' and 'tone-deaf' used to describe offensive material.
    },
    Rhetorical Strategy (Emphasis and Defiance): {
        definition: Use of rhetorical devices (e.g., sarcasm) to emphasize points and express defiance.,
        example: 'If anyone digs a hole this deep…' as a sarcastic way to emphasize the other person’s incorrect stance.
    }
}

# General Refining Process

refining_process = {
    Syntactizing Similar Codes: Merging codes that have overlapping concepts to ensure clarity.,
    Clarifying Definitions: Ensure each code has a clear, concise definition that captures its essence.,
    Incorporating Intersectionality: Explicitly discuss how these themes interact with intersectional identities.,
    Emphasizing Power Dynamics: Given the discursive nature of the text, keep power dynamics at the center.,
    Illustrating Examples: Include textual examples to support each code.,
    Iterative Feedback Loop: Allow multiple iterations for feedback and refinement.
}

# Final Thematic Coding Example

final_thematic_coding_example = {
    Denial or Minimization of Racism: {
        example: ‘It’s not racist; it’s just that it looks bad.’
    },
    Claims of Authority Based on Geography and Ethnicity: {
